-- Chocoloom Master SQL Script for Supabase (ALL PRODUCTS IN APP WITH SIZE PRICING & SIZE-BASED COOLING CHARGES)
-- Adds explicit size price columns for product prices AND cooling charges (1/2 KG: ₹50, 1 KG: ₹100, 1 1/2 KG: ₹150, 2 KG: ₹200, 3 KG: ₹300) so you can view & edit any size cooling price directly in Supabase!
-- Run this in Supabase SQL Editor (SQL Editor -> New Query -> Run)

-- STEP 1: Add columns for size pricing & size-based cooling charges if they do not exist yet
ALTER TABLE products 
  ADD COLUMN IF NOT EXISTS price_half_kg NUMERIC,
  ADD COLUMN IF NOT EXISTS price_1kg NUMERIC,
  ADD COLUMN IF NOT EXISTS price_1_5kg NUMERIC,
  ADD COLUMN IF NOT EXISTS price_2kg NUMERIC,
  ADD COLUMN IF NOT EXISTS price_3kg NUMERIC,
  ADD COLUMN IF NOT EXISTS cooling_price_half_kg NUMERIC DEFAULT 50.0,
  ADD COLUMN IF NOT EXISTS cooling_price_1kg NUMERIC DEFAULT 100.0,
  ADD COLUMN IF NOT EXISTS cooling_price_1_5kg NUMERIC DEFAULT 150.0,
  ADD COLUMN IF NOT EXISTS cooling_price_2kg NUMERIC DEFAULT 200.0,
  ADD COLUMN IF NOT EXISTS cooling_price_3kg NUMERIC DEFAULT 300.0;

-- STEP 2: Clear old/duplicate product entries to avoid legacy ID conflicts
TRUNCATE TABLE products RESTART IDENTITY;

-- STEP 3: Insert all current app products with complete size pricing & size-based cooling charges
INSERT INTO products (id, name, description, price, discount_price, price_half_kg, price_1kg, price_1_5kg, price_2kg, price_3kg, cooling_price_half_kg, cooling_price_1kg, cooling_price_1_5kg, cooling_price_2kg, cooling_price_3kg, image_url, category, stock, is_available)
